import { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, Link } from "react-router-dom";
import axios from "axios";

// Components
import AdminPanel from "./components/AdminPanel";
import AdminCodesPanel from "./components/AdminCodesPanel";
import AdminAnonymousResults from "./components/AdminAnonymousResults";
import AuthPage from "./components/Authpage";
import UserDashboard from "./components/UserDashboard";
import VotingPage from "./components/VotingPage";
import CandidatesPage from "./components/CandidatesPage";
import MyVotesPage from "./components/MyVotesPage";

const API_URL = "http://localhost:5000";

function App() {

  const [candidates, setCandidates] = useState([]);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");
  const [hasVoted, setHasVoted] = useState(false);

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token"),
    role: localStorage.getItem("role"),
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    partylist: "",
    yearLevel: "",
    block: "",
    description: "",
    image: null,
  });

  const [selectedVotes, setSelectedVotes] = useState({});

  const theme = {
    background: "#f1f5f9",
    navbar: "#ffffff",
    card: "#ffffff",
    text: "#0f172a",
    button: "#6366f1",
  };

  // ================= FETCH CANDIDATES =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  // ================= CHECK IF USER VOTED =================
  useEffect(() => {

    const fetchMyVotes = async () => {

      if (!auth.token) return;

      try {

        const res = await axios.get(`${API_URL}/api/vote/my`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });

        setHasVoted(res.data.length > 0);

      } catch (err) {

        console.log("Vote check failed");

      }

    };

    fetchMyVotes();

  }, [auth.token]);

  // ================= LOGOUT =================
  const handleLogout = () => {

    localStorage.removeItem("token");
    localStorage.removeItem("role");

    setAuth({
      token: null,
      role: null
    });

  };

  // ================= SHOW LOGIN IF NOT AUTH =================
  if (!auth.token) {

    return (
      <AuthPage
        setAuth={(data) => {

          localStorage.setItem("token", data.token);

          if (data.role) {
            localStorage.setItem("role", data.role);
          }

          setAuth({
            token: data.token,
            role: data.role || "user",
          });

        }}
      />
    );

  }

  // ================= ADMIN FUNCTIONS =================
  const handleSaveCandidate = async () => {

    try {

      const formData = new FormData();

      Object.keys(candidateForm).forEach((key) => {

        if (candidateForm[key]) {
          formData.append(key, candidateForm[key]);
        }

      });

      if (editId) {

        await axios.put(
          `${API_URL}/api/candidates/${editId}`,
          formData,
          { headers: { Authorization: `Bearer ${auth.token}` } }
        );

        setMessage("Candidate updated");

      } else {

        await axios.post(
          `${API_URL}/api/candidates`,
          formData,
          { headers: { Authorization: `Bearer ${auth.token}` } }
        );

        setMessage("Candidate added");

      }

      fetchCandidates();

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        partylist: "",
        yearLevel: "",
        block: "",
        description: "",
        image: null
      });

      setEditId(null);

    } catch {

      setMessage("Save failed");

    }

  };

  const handleDeleteCandidate = async (id) => {

    try {

      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });

      fetchCandidates();

    } catch {

      alert("Delete failed");

    }

  };

  // ================= VOTE =================
  const handleVoteSubmit = async () => {

    const candidateIds = Object.values(selectedVotes);

    if (candidateIds.length === 0) {
      alert("Select candidate first");
      return;
    }

    try {

      await axios.post(
        `${API_URL}/api/vote/batch`,
        { candidateIds },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      alert("Vote submitted!");

      setSelectedVotes({});
      setHasVoted(true);

    } catch {

      alert("Vote failed");

    }

  };

  const totalVotes = candidates.reduce((sum, c) => sum + (c.votes || 0), 0);

  return (

    <Router>

      <div style={{ minHeight: "100vh", background: theme.background }}>

        {/* NAVBAR */}
        <div
          style={{
            background: theme.navbar,
            padding: "18px 40px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            boxShadow: "0 2px 10px rgba(0,0,0,0.08)"
          }}
        >

          <h2>SorSU Online Voting</h2>

          <div style={{ display: "flex", gap: 10 }}>

            {auth.role === "user" && (
              <>
                <Link to="/candidates" style={modernButton(theme)}>Candidates</Link>
                <Link to="/vote" style={modernButton(theme)}>Vote</Link>
                {hasVoted && (
                  <Link to="/my-votes" style={modernButton(theme)}>My Ballot</Link>
                )}
              </>
            )}

            <button
              onClick={handleLogout}
              style={{ ...modernButton(theme), background: "#ef4444" }}
            >
              Logout
            </button>

          </div>

        </div>

        {/* ROUTES */}
        <div style={{ maxWidth: 1200, margin: "40px auto" }}>

          {auth.role === "admin" && (

            <>
              <h2>Admin Panel</h2>

              <div style={{ marginBottom: 20 }}>
                <strong>Total Votes:</strong> {totalVotes}
              </div>

              <AdminPanel
                candidateForm={candidateForm}
                setCandidateForm={setCandidateForm}
                onSave={handleSaveCandidate}
                editId={editId}
                setEditId={setEditId}
                onDelete={handleDeleteCandidate}
                candidates={candidates}
                auth={auth}
              />

              <AdminCodesPanel />

            </>

          )}

          {auth.role === "user" && (

            <Routes>

              <Route
                path="/dashboard"
                element={
                  <UserDashboard
                    candidates={candidates}
                    selectedVotes={selectedVotes}
                    setSelectedVotes={setSelectedVotes}
                    handleVoteSubmit={handleVoteSubmit}
                    electionClosed={electionClosed}
                  />
                }
              />

              <Route
                path="/vote"
                element={<VotingPage auth={auth} electionClosed={electionClosed} />}
              />

              <Route
                path="/candidates"
                element={<CandidatesPage auth={auth} />}
              />

              <Route
                path="/my-votes"
                element={<MyVotesPage auth={auth} />}
              />

              <Route path="*" element={<Navigate to="/dashboard" />} />

            </Routes>

          )}

        </div>

      </div>

    </Router>

  );

}

const modernButton = (theme) => ({
  padding: "8px 14px",
  background: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  textDecoration: "none"
});

export default App;
